CREATE TABLE IF NOT EXISTS vehicles (id BIGSERIAL PRIMARY KEY, reg_no TEXT NOT NULL UNIQUE, kind TEXT NOT NULL DEFAULT 'bus' CHECK (kind IN ('bus','van','car','other')), capacity INT NOT NULL DEFAULT 1 CHECK (capacity>0), driver_name TEXT NULL, driver_phone TEXT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS transport_routes (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, vehicle_id BIGINT NULL REFERENCES vehicles(id) ON DELETE SET NULL, fee_cents BIGINT NOT NULL DEFAULT 0 CHECK (fee_cents>=0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS transport_stops (id BIGSERIAL PRIMARY KEY, route_id BIGINT NOT NULL REFERENCES transport_routes(id) ON DELETE CASCADE, name TEXT NOT NULL, sequence INT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS transport_riders (id BIGSERIAL PRIMARY KEY, student_id BIGINT NOT NULL REFERENCES students(id) ON DELETE CASCADE, route_id BIGINT NOT NULL REFERENCES transport_routes(id) ON DELETE CASCADE, stop_id BIGINT NULL REFERENCES transport_stops(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (student_id, route_id));
CREATE INDEX IF NOT EXISTS idx_riders_student ON transport_riders (student_id);
CREATE INDEX IF NOT EXISTS idx_stops_route ON transport_stops (route_id, sequence);